class Usuario {
  function getNome() {
    return this.nome;
  }
}

#include <iostream>

class Contador {
public:
    int valor;
    Contador(int v) : valor(v) {}
    void incrementar() {
        valor++;
    }
};

int main() {
    Contador c(5);
    c.incrementar();
    std::cout << c.valor;
    return 0;
}
